sys_script_include.script:
var WeatherAjax = Class.create();

WeatherAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getWeather: function() {
        var city = this.getParameter('sysparm_city');
        if (!city) {
            return JSON.stringify({ success: false, error: 'City parameter is required' });
        }
        city = city.toString().trim();
        if (city.length < 2) {
            return JSON.stringify({ success: false, error: 'City name must be at least 2 characters' });
        }

        try {
            var rm = new sn_ws.RESTMessageV2('WeatherAPI', 'getCurrentWeather');
            rm.setStringParameterNoEscape('key', 'cda8d818671c49ac8e4144728262907');
            rm.setStringParameterNoEscape('city', city);
            rm.setHttpTimeout(15000);

            var response = rm.execute();
            var httpStatus = response.getStatusCode();
            var body = response.getBody();

            gs.info('WeatherAjax: API response status=' + httpStatus + ' for city=' + city);

            if (httpStatus == 200) {
                var data = JSON.parse(body);
                return JSON.stringify({
                    success: true,
                    temp_c: data.current.temp_c,
                    condition: data.current.condition.text
                });
            } else {
                gs.error('WeatherAjax: API error status=' + httpStatus + ' body=' + body);
                return JSON.stringify({ success: false, error: 'API returned status ' + httpStatus });
            }
        } catch (ex) {
            gs.error('WeatherAjax: Exception - ' + ex.getMessage());
            return JSON.stringify({ success: false, error: 'Exception: ' + ex.getMessage() });
        }
    },

    type: 'WeatherAjax'
});
